// Cuentas sugeridas para pagar: primero las que tienen saldo suficiente (bolsillos incluidos), mostrando el saldo; la tarjeta al final
const corto = v => v >= 1e6 ? '$' + (Math.round(v / 1e5) / 10).toString().replace('.', ',') + ' M' : v >= 1e3 ? '$' + Math.round(v / 1e3) + ' mil' : pesos(v);
const conPlata = (montoX, excluir) => cuentas.filter(c => !['Tarjeta de crédito', 'CDT', 'Inversión'].includes(c.Tipo) && c.saldo != null && c.saldo >= montoX && c.ID !== excluir).sort((x, y) => y.saldo - x.saldo);
const sugerir = (montoX, credito, excluir) => {
  const otras = conPlata(montoX, excluir).map(c => c.ID);
  for (const id of principales) if (!otras.includes(id) && id !== excluir && ctaDe(id).Tipo !== 'Tarjeta de crédito') otras.push(id);
  const ops = otras.slice(0, 5).map(id => ({ texto: `${nombreDe(id)} · ${corto(Math.max(0, ctaDe(id).saldo || 0))}`.slice(0, 28), valor: id }));
  if (credito) for (const t of tarjetas) if (t.ID !== excluir) { const disp = t.Cupo - t.saldo; ops.splice(3, 0, { texto: `${t.Nombre} · ${disp >= montoX ? 'cupo ' + corto(disp) : 'sin cupo'}`.slice(0, 28), valor: t.ID }); }
  return ops.slice(0, 5);
};
const SALEN = ['Gasto', 'Transferencia', 'Pago tarjeta', 'Préstamo dado', 'Abono pagado'];
// ¿La cuenta quedaría en negativo? (solo cuentas con saldo, y movimientos que afectan el saldo actual)
const quedaNegativa = (id, montoX, fechaX, yaUsado = 0) => { const c = ctaDe(id); if (!c.ID || ['Tarjeta de crédito', 'CDT', 'Inversión'].includes(c.Tipo) || c.saldo == null) return null; if (c.ancla && fechaX && fechaX < c.ancla) return null; const r = c.saldo - yaUsado - montoX; return r < 0 ? r : null; };
const TIPOS = { gasto: 'Gasto', ingreso: 'Ingreso', transferencia: 'Transferencia', 'pago tarjeta': 'Pago tarjeta', pago_tarjeta: 'Pago tarjeta',
  'prestamo dado': 'Préstamo dado', 'abono recibido': 'Abono recibido', 'prestamo recibido': 'Préstamo recibido', 'abono pagado': 'Abono pagado' };
const CON_PERSONA = ['Préstamo dado', 'Abono recibido', 'Préstamo recibido', 'Abono pagado'];
// ---------- Personas (v10): nombre, alias o relación; las que nombra el mensaje mandan ----------
const PARENTESCO = /^(?:(?:a |de |con |para )?(?:mi |mis |la |el |su |los |las ))?(mama|mami|madre|papa|papi|padre|hermano|hermana|tio|tia|abuelo|abuela|primo|prima|novio|novia|esposo|esposa|suegro|suegra|hijo|hija|cunado|cunada|sobrino|sobrina|padrino|madrina|jefe|jefa)$/;
const sinArticulo = s => s.replace(/^(?:a |de |con |para )?(?:mi |mis |la |el |su |los |las )/, '').trim();
const aliasDe = x => String(x.alias || '').split(',').map(norm).filter(Boolean);
const personaExistente = v => {
  if (!v) return null;
  const s = norm(v), s2 = sinArticulo(s);
  const exacta = x => [s, s2].some(t => t && (norm(x.nombre) === t || aliasDe(x).includes(t)));
  let p = ctx.deudas.find(exacta);
  if (!p) { const rel = ctx.deudas.filter(x => x.relacion && [s, s2].includes(norm(x.relacion))); if (rel.length === 1) p = rel[0]; }
  if (!p && s2.length > 2 && !PARENTESCO.test(s)) p = ctx.deudas.find(x => norm(x.nombre).includes(s2));
  return p ? p.nombre : null;
};
// Texto original del mensaje (o la transcripción de la nota de voz) y personas que nombra
const textoOrig = norm(d.transcripcion || (n.tipo_update === 'mensaje' && !cmd.startsWith('/') ? n.texto : ''));
const escRe = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const conPalabra = (txt, w) => !!txt && w.length > 2 && new RegExp('(^|[^a-z0-9])' + escRe(w) + '([^a-z0-9]|$)').test(txt);
const enTexto = textoOrig ? ctx.deudas.filter(x => x.nombre !== 'Por definir' && [norm(x.nombre), ...aliasDe(x)].some(w => conPalabra(textoOrig, w))).map(x => x.nombre) : [];
const persDe = nombre => ctx.deudas.find(x => x.nombre === nombre) || { nombre, informal: 0, cuotas: 0, total: 0 };
const deudores = () => ctx.deudas.filter(x => x.total > 0 && x.nombre !== 'Por definir').sort((x, y) => y.total - x.total);
const opsPersonas = lista => lista.slice(0, 5).map(x => ({ texto: `${x.nombre}${x.total > 0 ? ' · ' + corto(x.total) : ''}`.slice(0, 28), valor: x.nombre }));
// Alias que aprende: solo si la palabra está en el mensaje (nunca un nombre que haya inventado la IA)
const aliasAprendible = crudo => { const t = sinArticulo(norm(crudo)); return t && conPalabra(textoOrig, t) && !personaExistente(crudo) ? norm(crudo) : null; };
const tarjetas = cuentas.filter(c => c.Tipo === 'Tarjeta de crédito');
let pregunta = null;
const confirmar = texto => { if (!d.confirmado && !pregunta) pregunta = { tipo: 'confirmar', texto, opciones: [{ texto: '✅ Sí', valor: 'si' }] }; };
const charla = r => [{ json: { accion: 'charla', respuesta: r } }];

// v14: link del tablero (Apps Script). Se guarda en Parámetros → url_tablero (no va fijo en el flujo)
if (a === 'tablero') {
  const URL_OK = /^https:\/\/script\.google\.com\/(a\/[^/\s]+\/)?macros\/s\/[A-Za-z0-9_-]+\/exec$/;
  const guardada = String((($('Tablas').first().json['Parámetros'] || []).find(r => r.Clave === 'url_tablero') || {}).Valor || '').trim();
  if (d.url) {
    const u = String(d.url).trim().replace(/[)>.,;]+$/, '');
    if (/\/dev$/.test(u)) return charla('Ese link termina en /dev: es el de pruebas y solo abre desde el editor. Mándame el que termina en /exec (Implementar → Administrar implementaciones).');
    if (!URL_OK.test(u)) return charla('Ese no parece el link del tablero. Debe empezar por https://script.google.com/macros/s/ y terminar en /exec.');
