  } else if (guardada) return charla(`📊 Tu tablero de finanzas:\n${guardada}\n\nÁbrelo en Chrome con tu cuenta de Google. Si dice que no se puede abrir, usa una ventana de incógnito o un navegador donde solo tengas esa cuenta.`);
  else return charla('Todavía no tengo el link de tu tablero. En la hoja abre el menú 📊 Tablero → Ver enlace para el celular, cópialo y mándamelo así:\n/tablero https://script.google.com/macros/s/…/exec');
}

// ---------- Cobros (v10): "X me pagó" decide entre préstamo con cuotas y deuda suelta, nunca cambia a la persona y siempre confirma ----------
const PIDE_TODO = /(^|[^a-z])(todo|toda la deuda|lo que me debia|lo que me debe|completo|paz y salvo)([^a-z]|$)/;
// Un "Abono recibido" suelto que mande la IA entra por el mismo camino (salvo comprobantes, que ya confirman)
if (a === 'registrar' && !d.desde_cobro && d.origen !== 'Comprobante' && Array.isArray(d.movimientos) && d.movimientos.length === 1 && TIPOS[norm(d.movimientos[0].tipo)] === 'Abono recibido') {
  const m0 = d.movimientos[0];
  a = 'cobrar_cuota';
  d = { ...d, accion: a, persona: m0.persona, monto: m0.monto, cuenta: m0.cuenta, prestamo: null, movimientos: undefined };
}
if (a === 'cobrar_cuota' && d.cuota_id && !d.cobro_listo) {   // v13: viene del aviso de cuota del Programado
  const qc = ($('Tablas').first().json['Cuotas préstamo'] || []).find(x => x.ID === d.cuota_id);
  if (!qc || ['Pagada', 'Anulada'].includes(qc.Estado)) return charla(`La cuota ${qc ? qc['Nº'] + ' de ' + qc.Persona : 'de ese aviso'} ya estaba registrada 👍. No registré nada.`);
  d.monto = Math.round(num(qc['Valor cuota']) - num(qc['Valor recibido'])) || d.monto;   // lo que falte hoy, por si abonó algo después del aviso
}
if (a === 'cobrar_cuota' && !d.cobro_listo) {
  const pIA = d.prestamo ? ctx.prestamos.find(x => norm(x.ID) === norm(d.prestamo)) : null;
  let quien = d.persona_ok ? d.persona : personaExistente(d.persona);
  if (!d.persona_ok) {
    if (enTexto.length === 1) quien = enTexto[0];                          // la persona que nombró manda sobre la IA
    else if (enTexto.length > 1) quien = enTexto.includes(quien) ? quien : null;
    else if (!quien && pIA && !textoOrig) quien = pIA.persona;              // sin texto (comando o botón): vale el préstamo
  }
  if (!quien) {
    const crudo = d.persona ? String(d.persona).trim() : '';
    const lista = deudores();
    if (!lista.length) return charla('Nadie te debe nada registrado 🙌. Si alguien te pagó algo que no tenía anotado, dímelo como ingreso.');
    const ops = opsPersonas(enTexto.length > 1 ? lista.filter(x => enTexto.includes(x.nombre)) : lista);
    if (crudo && !PARENTESCO.test(norm(crudo)) && ops.length < 5) ops.push({ texto: `Otra: ${crudo}`.slice(0, 28), valor: crudo.charAt(0).toUpperCase() + crudo.slice(1) });
    d.alias_nuevo = crudo ? aliasAprendible(crudo) : null;
    pregunta = { idx: null, campo: 'persona', texto: crudo ? `¿Quién es "${crudo}"? No lo tengo en tus personas. ¿Quién te pagó?` : (enTexto.length > 1 ? `Nombraste a ${enTexto.join(' y ')}. ¿Quién te pagó?` : '¿Quién te pagó? Estas personas te deben:'), opciones: ops };
  } else {
    d.persona = quien;
    const dd = persDe(quien);
    const prestP = ctx.prestamos.filter(x => x.persona === quien && x.pendientes > 0);
    const todo = d.todo === true || PIDE_TODO.test(textoOrig);
    let destino = d.destino || null;
    if (!destino) {
      const diceCuota = /(^|[^a-z])cuotas?([^a-z]|$)/.test(textoOrig);
      if (pIA && pIA.persona === quien && pIA.pendientes > 0) destino = pIA.ID;           // la IA nombró un préstamo de esa misma persona
      else if (prestP.length === 1 && (dd.informal <= 0 || diceCuota)) destino = prestP[0].ID;
      else if (!prestP.length && dd.informal > 0) destino = 'suelta';
    }
    if (!destino) {
      if (!prestP.length && dd.informal <= 0) return charla(`${quien} no te debe nada registrado 🙌. Escribe /deudas para ver quién te debe.`);
      pregunta = { idx: null, campo: 'destino', texto: `${quien} te debe ${pesos(dd.total)}. ¿A qué abona ${todo ? 'el pago' : 'lo que te pagó'}?`,
        opciones: [...prestP.slice(0, 3).map(p => ({ texto: `Préstamo ${p.ID} · ${corto(p.saldo)}`.slice(0, 28), valor: p.ID })), ...(dd.informal > 0 ? [{ texto: `Lo suelto · ${corto(dd.informal)}`.slice(0, 28), valor: 'suelta' }] : [])] };
