      d.cobro_listo = true;
    }
  }
}

// ---------- Movimientos ----------
if (a === 'registrar' || a === 'corregir') {
  if (a === 'corregir' && !d.operacion && ctx.respondido.length) d.operacion = ctx.respondido[0]['Operación'];
  const lista = (Array.isArray(d.movimientos) ? d.movimientos : []).map(m => {
    const tipo = TIPOS[norm(m.tipo)] || m.tipo;
    let f = m.fecha ? fecha(m.fecha) : ahora; if (!f.isValid) f = ahora;
    return {
      tipo, monto: Math.round(Math.abs(monto(m.monto))), cuenta: buscarCuenta(m.cuenta), cuenta_destino: buscarCuenta(m.cuenta_destino),
      persona: CON_PERSONA.includes(tipo) ? (m.persona_ok ? m.persona : buscarPersona(m.persona || m.persona_sugerida)) : null, persona_txt: m.persona_txt || m.persona || m.persona_sugerida || '',
      tipo_ok: m.tipo_ok || undefined, persona_sugerida: m.persona_sugerida || undefined,
      persona_ok: m.persona_ok || undefined, cuenta_ok: m.cuenta_ok || undefined, alias_nuevo: m.alias_nuevo || undefined,
      categoria: (tipo === 'Gasto' || tipo === 'Ingreso') ? buscarCat(m.categoria) : null,
      categoria_opciones: (m.categoria_opciones || []).map(buscarCat).filter(Boolean).slice(0, 3),
      comercio: m.tipo_ok && tipo === 'Préstamo dado' ? '' : (m.comercio || ''),
      detalle: m.tipo_ok && tipo === 'Préstamo dado' ? `Préstamo${m.persona_sugerida ? ' a ' + m.persona_sugerida : ''}` : String(m.detalle || m.comercio || tipo).trim(),
      fecha: f.toFormat('yyyy-MM-dd'), hora: m.hora || (f.hasSame(ahora, 'day') ? ahora.toFormat('HH:mm') : ''),
      cuotas: Math.max(1, Math.min(48, parseInt(m.cuotas) || 1)), pago: m.pago || null,
      referencia: m.referencia || '', confianza: m.confianza || '', dudas: Array.isArray(m.dudas) ? m.dudas : []
    };
  }).filter(m => Object.values(TIPOS).includes(m.tipo));
  lista.forEach(m => {
    if (m.tipo === 'Pago tarjeta' && !m.cuenta_destino && tarjetas.length === 1) m.cuenta_destino = tarjetas[0].ID;
    if (m.tipo === 'Pago tarjeta' && m.pago && !m.monto) {
      const t = ctx.tarjetas.find(x => x.ID === m.cuenta_destino);
      if (t) { m.monto = Math.round(m.pago === 'total' ? t.total : t.minimo); m.detalle = m.pago === 'total' ? 'Pago total de la tarjeta' : 'Pago mínimo de la tarjeta'; }
    }
  });
  if (!lista.length || lista.some(m => !m.monto)) return charla('No entendí bien el monto o qué registrar. ¿Me lo dices así: "almuerzo 25 mil con Nequi"?');
  const sinPersona = lista.find(m => CON_PERSONA.includes(m.tipo) && !m.persona);
  if (sinPersona) return charla(`¿Quién? Dime el nombre de la persona para registrar ${pesos(sinPersona.monto)} (${sinPersona.detalle}).`);
  if (d.origen === 'Comprobante' && !d.dudas_aplicadas) lista.forEach(m => { if (m.dudas.includes('cuenta')) m.cuenta = null; if (m.dudas.includes('categoria')) m.categoria = null; });
  d.dudas_aplicadas = true;
  d.movimientos = lista;
  // v10: en Préstamo dado / recibido / Abono pagado, la persona debe ser la que nombró (nunca otra por contexto) y un parentesco desconocido se pregunta
  for (let i = 0; i < lista.length && !pregunta; i++) {
    const m = lista[i];
    if (!CON_PERSONA.includes(m.tipo) || m.persona_ok || !textoOrig || d.desde_cobro) continue;
    const conocida = personaExistente(m.persona_txt);
    if (conocida && enTexto.length && !enTexto.includes(conocida)) {
      pregunta = { idx: i, campo: 'persona', texto: `¿De quién es "${m.detalle}" (${pesos(m.monto)})?`, opciones: opsPersonas(enTexto.map(persDe)).concat([{ texto: conocida.slice(0, 28), valor: conocida }]).slice(0, 5) };
    } else if (!conocida && PARENTESCO.test(norm(m.persona_txt))) {
      if (enTexto.length === 1) { m.persona = enTexto[0]; continue; }
      const fam = ctx.deudas.filter(x => /famil/i.test(x.relacion || '') || x.total > 0).sort((x, y) => y.total - x.total);
      m.alias_nuevo = aliasAprendible(m.persona_txt);
      pregunta = { idx: i, campo: 'persona', texto: `¿Quién es "${m.persona_txt}"? No lo tengo en tus personas.`, opciones: opsPersonas(fam) };
    }
  }
  // v11: si dijo "presté"/"le prestó" y la IA lo dejó como Gasto, se pregunta (error del 2-oct: préstamo a Nicolás quedó como gasto de Spotify)
  const DICE_PRESTE = /(^|[^a-z])(preste|prestaste|le preste|les preste|prestado|prestamo a|le di prestad[oa]s?|le preste)([^a-z]|$)/;
  if (!pregunta && DICE_PRESTE.test(textoOrig) && !lista.some(m => m.tipo === 'Préstamo dado') && d.origen !== 'Comprobante') {
    const i = lista.findIndex(m => m.tipo === 'Gasto' && !m.tipo_ok);
    if (i >= 0) {
      const m = lista[i];
      // Nombre sugerido: una persona conocida que nombró, o la palabra después de "presté … a" tal como la dijo (con tildes)
      const crudoTxt = String(d.transcripcion || n.texto || '').toLowerCase();
      const sug = enTexto[0] || (() => { const x = crudoTxt.match(/pr[eé]st(?:e|é|ado|amo)[^a-záéíóúñü]+(?:.*?\s)?a\s+([a-záéíóúñü]+(?:\s+[a-záéíóúñü]+)?)/); const w = x ? x[1].replace(/\s+(para|por|de|del|en|con|que|y|la|el)(\s.*)?$/, '').trim() : ''; return w && !/^(mi|mis|la|el|su|un|una|los|las)$/.test(w) ? w.split(' ').map(t => t.charAt(0).toUpperCase() + t.slice(1)).join(' ') : ''; })();
      m.persona_sugerida = sug || undefined;
      pregunta = { idx: i, campo: 'tipo', texto: `Dijiste "presté", pero lo entendí como gasto: "${m.detalle}" (${pesos(m.monto)}). ¿Qué es?`,
        opciones: [{ texto: `🤝 Préstamo${sug ? ' a ' + sug : ''}`.slice(0, 28), valor: 'Préstamo dado' }, { texto: '🧾 Gasto mío', valor: 'Gasto' }] };
    }
  }
  // Abono que viene de "X me pagó": confirmación con lo que queda debiendo (la pregunta de cuenta ya trae el resumen)
  if (d.desde_cobro && !pregunta) {
    const m = lista[0], queda = Math.max(0, (d.debia || 0) - m.monto);
    const resumen = `• ${m.persona}: ${pesos(m.monto)} de lo que te debe suelto\n• ${queda > 0 ? `Le quedaría debiendo ${pesos(queda)}` : 'Quedaría a paz y salvo 🎉'}` + (m.monto > (d.debia || 0) + 1 ? `\n⚠️ Es más de lo que te debe (${pesos(d.debia || 0)}).` : '');
    if (!m.cuenta) pregunta = { idx: 0, campo: 'cuenta', texto: `¿A qué cuenta te llegó este pago? Al elegirla lo registro.\n${resumen}`, opciones: opsCuentas(principalesDestino) };
    else if (!m.cuenta_ok) confirmar(`¿Registro este pago en ${nombreDe(m.cuenta)}?\n${resumen}`);
  }
  for (let i = 0; i < lista.length && !pregunta; i++) {
    const m = lista[i], desc = `"${m.detalle}" (${pesos(m.monto)})`;
    const entra = ['Ingreso', 'Abono recibido', 'Préstamo recibido'].includes(m.tipo);
    if (!m.cuenta) pregunta = { idx: i, campo: 'cuenta', texto: entra ? `¿A qué cuenta te llegó ${desc}?` : `¿De dónde salió la plata de ${desc}?`, opciones: entra ? opsCuentas(principalesDestino) : sugerir(m.monto, ['Gasto', 'Préstamo dado'].includes(m.tipo)) };
    else if ((m.tipo === 'Transferencia' || m.tipo === 'Pago tarjeta') && !m.cuenta_destino)
      pregunta = { idx: i, campo: 'cuenta_destino', texto: `¿A qué cuenta va ${desc}?`, opciones: opsCuentas(m.tipo === 'Pago tarjeta' ? tarjetas.map(t => t.ID) : principalesDestino.filter(id => id !== m.cuenta)) };
    else if ((m.tipo === 'Gasto' || m.tipo === 'Ingreso') && !m.categoria) {
      let ops = m.categoria_opciones.slice();
      for (const e of (m.tipo === 'Gasto' ? ['Comida', 'Mercado', 'Otros'] : ['Salario', 'Negocio', 'Otros ingresos'])) if (ops.length < 3 && !ops.includes(e) && buscarCat(e)) ops.push(e);
      pregunta = { idx: i, campo: 'categoria', texto: `¿En qué categoría va ${desc}?`, opciones: ops.slice(0, 3).map(c => ({ texto: c, valor: c })) };
    }
  }
  // Si una cuenta quedaría en negativo, se pregunta antes de registrar (salvo que él ya la haya elegido)
  const usado = {};
  // v12: al corregir, los movimientos que se van a reemplazar (misma operación, 4x1000 incluido) no cuentan para el saldo
  if (a === 'corregir' && d.operacion) {
    const opC = d.operacion;
    for (const r of $('Leer movimientos').all().map(i => i.json).filter(r => r.ID && r['Operación'] === opC)) {
      const v = num(r.Monto), suma = (id, x) => { if (id) usado[id] = (usado[id] || 0) + x; };
      if (SALEN.includes(r.Tipo)) suma(r.Cuenta, -v);
      else if (['Ingreso', 'Abono recibido', 'Préstamo recibido', 'Cobro cuota', 'Venta reventa'].includes(r.Tipo)) suma(r.Cuenta, v);
      if (['Transferencia', 'Pago tarjeta'].includes(r.Tipo)) suma(r['Cuenta destino'], v);
    }
  }
  for (let i = 0; i < lista.length && !pregunta; i++) {
    const m = lista[i];
    if (!SALEN.includes(m.tipo) || m.cuenta_ok || d.confirmado) continue;
    const neg = quedaNegativa(m.cuenta, m.monto, m.fecha, usado[m.cuenta] || 0);
    usado[m.cuenta] = (usado[m.cuenta] || 0) + m.monto;
    if (neg !== null) {
      const alt = sugerir(m.monto, ['Gasto', 'Préstamo dado'].includes(m.tipo), m.cuenta).slice(0, 4);
      pregunta = { idx: i, campo: 'cuenta', texto: `${nombreDe(m.cuenta)} quedaría en ${pesos(neg)} con "${m.detalle}" (${pesos(m.monto)}). ¿Seguro que salió de ahí? Estas tienen saldo:`,
        opciones: [{ texto: `Sí, de ${nombreDe(m.cuenta)}`.slice(0, 28), valor: m.cuenta }, ...alt] };
    }
  }
  if (!pregunta && d.origen === 'Comprobante' && !d.confirmado) {
    const previos = $('Leer movimientos').all().map(i => i.json).filter(r => r.ID);
    const reps = lista.map(m => previos.find(r => Math.round(num(r.Monto)) === m.monto && String(r.Cuenta) === String(m.cuenta) && fecha(r.Fecha).isValid && fecha(r.Fecha).toFormat('yyyy-MM-dd') === m.fecha)).filter(Boolean);
    const dudoso = !d.respondio && lista.some(m => m.confianza !== 'alta' || m.dudas.length);
    if (reps.length || dudoso) confirmar((reps.length ? `⚠️ Esto se parece a algo que ya tienes registrado (${reps.map(r => r.Detalle || r.Tipo).join(', ')}).\n` : '') +
      'Leí esto del comprobante:\n' + lista.map(m => `• ${m.tipo} de ${pesos(m.monto)}${m.categoria ? ' en ' + m.categoria : ''} con ${nombreDe(m.cuenta)}${m.cuenta_destino ? ' → ' + nombreDe(m.cuenta_destino) : ''} (${m.detalle}), ${fecha(m.fecha).setLocale('es').toFormat("d 'de' LLLL")}`).join('\n') + '\n¿Lo registro?');
  }
  if (a === 'corregir') { if (!d.operacion) return charla('Para corregir, respóndeme directamente al mensaje de confirmación de ese registro.'); }
  else d.operacion = d.operacion || OP;
}

// ---------- Deshacer ----------
if (a === 'deshacer' && !(d.confirmado && d.operacion)) {
  const ultima = $('Leer movimientos').all().map(i => i.json).filter(r => String(r.ID || '').startsWith('MOV-')).sort((x, y) => String(y.ID).localeCompare(String(x.ID)))[0];
  if (!ultima) return charla('No encontré nada registrado por mí para deshacer.');
  d.operacion = ultima['Operación'];
  const filasOp = $('Leer movimientos').all().map(i => i.json).filter(r => r['Operación'] === d.operacion && r.Detalle !== '4x1000');
  confirmar('¿Deshago esto?\n' + filasOp.map(r => `• ${r.Detalle || r.Tipo}: ${pesos(num(r.Monto))} (${nombreDe(r.Cuenta) || 'sin cuenta'})`).join('\n'));
}

// ---------- Deudas ----------
if (a === 'asumir_deuda') {
  const nombre = buscarPersona(d.persona);
  const p = ctx.deudas.find(x => x.nombre === nombre);
  if (!p || p.informal <= 0) return charla(`${nombre || 'Esa persona'} no tiene deudas pendientes contigo (fuera de préstamos con cuotas).`);
  d.persona = nombre; d.monto = Math.min(Math.round(monto(d.monto)) || p.informal, p.informal); d.categoria = buscarCat(d.categoria) || 'Otros'; d.operacion = OP;
}
if (a === 'consultar_deudas' || a === 'cobrar') {
  // v11: el nombre se busca por nombre o alias; si no existe se dice, y /cobrar ofrece botones con quienes deben
  const crudo = d.persona ? String(d.persona).trim() : '';
  d.persona = d.persona_ok ? d.persona : (crudo ? personaExistente(crudo) : null);
  if (a === 'consultar_deudas' && crudo && !d.persona) return charla(`No encontré a "${crudo}" en tus personas. Escribe /deudas para ver quién te debe.`);
  if (a === 'cobrar' && (!d.persona || persDe(d.persona).total <= 0)) {
    const lista = deudores();
    if (!lista.length) return charla('Nadie te debe nada 🙌');
    const motivo = crudo && !d.persona ? `No encontré a "${crudo}" en tus personas. ` : d.persona ? `${d.persona} no te debe nada 🙌. ` : '';
    d.persona = null;
    pregunta = { idx: null, campo: 'persona', texto: `${motivo}¿A quién le cobro?${lista.length > 5 ? ' (o escribe /cobrar y el nombre)' : ''}`, opciones: opsPersonas(lista) };
  }
}

// ---------- Préstamos ----------
if (a === 'crear_prestamo') {
  const generico = /^(nuevo|prestamo|préstamo|alguien|persona|desconocid|sin nombre|x$)/i;
  d.persona = d.persona && !generico.test(String(d.persona).trim()) ? buscarPersona(d.persona) : 'Por definir';
  d.monto = Math.round(monto(d.monto));
  if (!d.monto) return charla('Para crear el préstamo dime cuánto y cómo te paga, por ejemplo: "le presté 500 mil a Juan, me paga 5 cuotas de 110 mil cada mes".');
  d.dias_pago = Array.isArray(d.dias_pago) ? [...new Set(d.dias_pago.map(x => parseInt(x)).filter(x => x >= 1 && x <= 31))].sort((x, y) => x - y) : [];
  if (d.dias_pago.length > 1) d.frecuencia = 'Quincenal';
  d.cuotas = Math.max(1, parseInt(d.cuotas) || 1); d.valor_cuota = Math.round(monto(d.valor_cuota)) || Math.round(d.monto / d.cuotas);
  d.frecuencia = ['Semanal', 'Quincenal', 'Mensual'].find(f => norm(f) === norm(d.frecuencia)) || 'Mensual';
  d.fecha = (d.fecha && fecha(d.fecha).isValid ? fecha(d.fecha) : ahora).toFormat('yyyy-MM-dd');
  d.primera_cuota = d.primera_cuota && fecha(d.primera_cuota).isValid ? fecha(d.primera_cuota).toFormat('yyyy-MM-dd') : '';
  d.cuenta = buscarCuenta(d.cuenta); d.cuenta_cobro = buscarCuenta(d.cuenta_cobro); d.operacion = OP;
  d.cuotas_tarjeta = Math.max(1, Math.min(48, parseInt(d.cuotas_tarjeta) || 1));
  const aQuien = d.persona === 'Por definir' ? '' : ` a ${d.persona}`;
  const negP = d.cuenta && !d.cuenta_ok ? quedaNegativa(d.cuenta, d.monto, d.fecha) : null;
  if (!d.cuenta) pregunta = { idx: null, campo: 'cuenta', texto: `¿De dónde salieron los ${pesos(d.monto)} que prestaste${aQuien}?`, opciones: sugerir(d.monto, true) };
  else if (negP !== null) pregunta = { idx: null, campo: 'cuenta', texto: `${nombreDe(d.cuenta)} quedaría en ${pesos(negP)}. ¿Seguro que salió de ahí? Estas tienen saldo:`, opciones: [{ texto: `Sí, de ${nombreDe(d.cuenta)}`.slice(0, 28), valor: d.cuenta }, ...sugerir(d.monto, true, d.cuenta).slice(0, 4)] };
  else confirmar(`¿Creo este préstamo?\n• ${d.persona === 'Por definir' ? 'Persona: por definir (me la dices después)' : d.persona}: ${pesos(d.monto)} desde ${nombreDe(d.cuenta)}${ctaDe(d.cuenta).Tipo === 'Tarjeta de crédito' ? ` a ${d.cuotas_tarjeta} cuota${d.cuotas_tarjeta > 1 ? 's' : ''} de la tarjeta` : ''}\n• ${d.cuotas} cuota${d.cuotas > 1 ? 's' : ''} de ${pesos(d.valor_cuota)} (${d.dias_pago.length ? 'los días ' + d.dias_pago.join(' y ') + ' de cada mes' : d.frecuencia.toLowerCase()})${d.primera_cuota ? ', la primera el ' + fecha(d.primera_cuota).setLocale('es').toFormat("d 'de' LLLL") : ''}\n• Te pagaría ${pesos(d.cuotas * d.valor_cuota)} en total (${pesos(d.cuotas * d.valor_cuota - d.monto)} de intereses)`);
}
if (a === 'modificar_prestamo') {
  const p = buscarPrestamo(d.id, d.persona);
  if (!p) return charla('No encontré ese préstamo. Escribe /prestamos para ver la lista.');
  d.id = p.ID; const c = { ...(d.cambios || {}) };
  if (c.persona) c.persona = buscarPersona(c.persona);
  if (c.cuenta) c.cuenta = buscarCuenta(c.cuenta);
  if (c.cuenta_cobro) c.cuenta_cobro = buscarCuenta(c.cuenta_cobro);
  for (const k of ['fecha', 'primera_cuota']) if (c[k]) c[k] = fecha(c[k]).isValid ? fecha(c[k]).toFormat('yyyy-MM-dd') : null;
  if (c.frecuencia) c.frecuencia = ['Semanal', 'Quincenal', 'Mensual'].find(f => norm(f) === norm(c.frecuencia)) || null;
  if (c.valor_cuota) c.valor_cuota = Math.round(monto(c.valor_cuota)) || null;
  if (c.cuotas) c.cuotas = parseInt(c.cuotas) || null;
  if (c.monto) c.monto = Math.round(monto(c.monto)) || null;
  const CONOCIDOS = ['persona', 'fecha', 'cuenta', 'primera_cuota', 'frecuencia', 'dias_pago', 'cuotas_pagadas', 'cuenta_cobro', 'valor_cuota', 'cuotas', 'monto'];
  const noSe = Object.keys(c).filter(k => !CONOCIDOS.includes(k));
  noSe.forEach(k => delete c[k]);
  if (Array.isArray(c.dias_pago)) { c.dias_pago = c.dias_pago.map(x => parseInt(x)).filter(x => x >= 1 && x <= 31).sort((x, y) => x - y); if (!c.dias_pago.length) delete c.dias_pago; }
  Object.keys(c).forEach(k => { if (c[k] === null || c[k] === undefined || c[k] === '') delete c[k]; });
  if (!Object.keys(c).length) return charla('¿Qué quieres cambiar del préstamo? Puedo cambiar: persona, fechas, frecuencia o días de pago, valor de la cuota, número de cuotas, monto, cuotas ya pagadas y la cuenta donde te paga.');
  d.cambios = c;
  if (c.valor_cuota) { const q0 = ($('Tablas').first().json['Cuotas préstamo'] || []).filter(q => q['ID préstamo'] === p.ID && !['Pagada', 'Anulada'].includes(q.Estado));
    const cap = q0.length ? num(q0[0].Capital) || num(q0[0]['Valor cuota']) : 0;
    d.nota_cuota = cap ? (c.valor_cuota >= cap ? `\n(Cada cuota: ${pesos(cap)} de capital + ${pesos(c.valor_cuota - cap)} de ganancia; aplica a las ${q0.length} cuotas pendientes.)` : `\n(Es ${pesos(cap - c.valor_cuota)} menos que el capital de cada cuota: queda como descuento.)`) : ''; }
  const et = { valor_cuota: 'Valor de cada cuota', cuotas: 'Número de cuotas', monto: 'Monto prestado', dias_pago: 'Días de pago', persona: 'Persona', fecha: 'Fecha del préstamo', cuenta: 'Cuenta de salida', primera_cuota: 'Primera cuota', frecuencia: 'Frecuencia', cuotas_pagadas: 'Cuotas ya pagadas', cuenta_cobro: 'Cuenta donde te paga' };
  confirmar(`¿Actualizo el préstamo ${p.ID} (${p.persona})?\n` + Object.entries(c).map(([k, v]) => `• ${et[k] || k}: ${['cuenta', 'cuenta_cobro'].includes(k) ? nombreDe(v) : ['valor_cuota', 'monto'].includes(k) ? pesos(v) : Array.isArray(v) ? v.join(' y ') : v}`).join('\n') +
    (d.nota_cuota || '') + (noSe.length ? `\n(Eso no lo sé cambiar: ${noSe.join(', ')}.)` : ''));
}
if (a === 'cobrar_cuota' && d.cobro_listo && !pregunta) {
  const p = ctx.prestamos.find(x => x.ID === d.prestamo);
  if (!p) return charla('No encontré un préstamo con cuotas para esa persona. Escribe /prestamos para verlos.');
  if (!p.pendientes) return charla(`El préstamo de ${p.persona} ya está pagado por completo 🎉`);
  d.cuenta = buscarCuenta(d.cuenta); d.operacion = d.operacion || OP;
  const queda = Math.max(0, p.saldo - d.monto);
  const resumen = `• ${p.persona}: ${pesos(d.monto)} al préstamo ${p.ID}\n• ${queda > 0 ? `Le quedaría debiendo ${pesos(queda)} de ese préstamo` : 'Terminaría de pagarte ese préstamo 🎉'}` +
    (d.monto > p.saldo + 1 ? `\n⚠️ Es más de lo que debe (${pesos(p.saldo)}); el sobrante lo sumo al capital.` : '');
  if (!d.cuenta) pregunta = { idx: null, campo: 'cuenta', texto: `¿A qué cuenta te llegó este pago? Al elegirla lo registro.\n${resumen}`, opciones: opsCuentas([p.cuenta_cobro, ...principalesDestino]) };
  else if (!d.cuenta_ok) confirmar(`¿Registro este pago en ${nombreDe(d.cuenta)}?\n${resumen}`);
}

// ---------- Cuentas ----------
if (a === 'crear_cuenta') {
  const tipos = ['Ahorros', 'Bolsillo', 'CDT', 'Tarjeta de crédito', 'Billetera', 'Efectivo', 'Inversión'];
  d.tipo = tipos.find(t => norm(t) === norm(d.tipo)) || (d.padre ? 'Bolsillo' : null);
  d.padre = buscarCuenta(d.padre);
  if (!d.nombre || !d.tipo) return charla('Para crear la cuenta dime el nombre y el tipo, por ejemplo: "crea un bolsillo en Nu que se llame Viajes, rinde 9%".');
  if (d.tipo === 'Bolsillo' && !d.padre) return charla(`¿En qué cuenta va el bolsillo "${d.nombre}"? (por ejemplo, Nu o Rappi)`);
  d.saldo_inicial = Math.round(monto(d.saldo_inicial)); d.operacion = OP;
  if (d.cupo) d.cupo = Math.round(monto(d.cupo));
  confirmar(`¿Creo esta cuenta?\n• ${d.nombre} (${d.tipo}${d.padre ? ', dentro de ' + nombreDe(d.padre) : ''})` + (d.tasa ? `\n• Rinde ${d.tasa}% EA` : '') + (d.cupo ? `\n• Cupo ${pesos(monto(d.cupo))}` : '') +
    (d.saldo_inicial ? (d.padre ? `\n• Paso ${pesos(d.saldo_inicial)} desde ${nombreDe(d.padre)}` : `\n• Saldo inicial ${pesos(d.saldo_inicial)}`) : ''));
}
if (a === 'modificar_cuenta') {
  d.cuenta = buscarCuenta(d.cuenta);
  if (!d.cuenta) return charla('No encontré esa cuenta. Escribe /saldos para ver sus nombres.');
  const c = { ...(d.cambios || {}) }; Object.keys(c).forEach(k => { if (c[k] === null || c[k] === '') delete c[k]; });
  if (c.cupo) c.cupo = Math.round(monto(c.cupo));
  if (Array.isArray(c.alias)) c.alias = c.alias.join(', ');
  if (!Object.keys(c).length) return charla('¿Qué quieres cambiar de esa cuenta? (nombre, tasa, cupo, día de corte o de pago, alias)');
  d.cambios = c;
  const et = { nombre: 'Nombre', tasa: 'Tasa EA (%)', cupo: 'Cupo', corte: 'Día de corte', pago: 'Día de pago', alias: 'Agregar alias', alias_quitar: 'Quitar alias' };
  confirmar(`¿Cambio esto en ${nombreDe(d.cuenta)}?\n` + Object.entries(c).map(([k, v]) => `• ${et[k] || k}: ${k === 'cupo' ? pesos(monto(v)) : v}`).join('\n'));
}
if (a === 'cerrar_cuenta') {
  d.cuenta = buscarCuenta(d.cuenta);
  if (!d.cuenta) return charla('No encontré esa cuenta. Escribe /saldos para ver sus nombres.');
  const c = ctaDe(d.cuenta);
  d.destino = buscarCuenta(d.destino) || (c.Padre || null);
  d.saldo = c.Tipo === 'Tarjeta de crédito' ? 0 : Math.round(c.saldo || 0); d.operacion = OP;
  if (d.saldo > 0 && !d.destino) pregunta = { idx: null, campo: 'destino', texto: `${c.Nombre} tiene ${pesos(d.saldo)}. ¿A qué cuenta los paso antes de cerrarla?`, opciones: opsCuentas(principalesDestino.filter(id => id !== d.cuenta)) };
  else confirmar(`¿Cierro ${c.Nombre}?` + (d.saldo > 0 ? `\n• Paso sus ${pesos(d.saldo)} a ${nombreDe(d.destino)}` : '') + '\n• Queda como cerrada (su historial se conserva)');
}
if (a === 'ajustar_saldo') {
  d.cuenta = buscarCuenta(d.cuenta);
  const c = ctaDe(d.cuenta);
  if (!d.cuenta || c.saldo === null || c.saldo === undefined) return charla('¿De qué cuenta es ese saldo? Dime, por ejemplo: "mi saldo real en Nequi es 312.400".');
  d.saldo_real = Math.round(monto(d.saldo_real));
  const esT = c.Tipo === 'Tarjeta de crédito';
  const dif = d.saldo_real - Math.round(c.saldo);
  if (Math.abs(dif) < 1) return charla(`Todo cuadra: ${c.Nombre} ${esT ? 'debe' : 'tiene'} ${pesos(c.saldo)} 👌`);
  d.diferencia = dif; d.operacion = OP;
  if (!d.clasificacion) {
    let ops;
    if (!esT) ops = dif > 0 ? [c.tasa ? 'Rendimiento' : null, 'Ingreso no anotado', 'Solo ajustar'] : ['Gasto no anotado', 'Comisión o 4x1000', 'Solo ajustar'];
    else ops = dif > 0 ? ['Compra no anotada', 'Intereses o cuota de manejo', 'Solo ajustar'] : ['Pago o reembolso no anotado', 'Solo ajustar'];
    pregunta = { idx: null, campo: 'clasificacion', texto: `Según mis registros ${c.Nombre} ${esT ? 'debe' : 'tiene'} ${pesos(c.saldo)} y me dices ${pesos(d.saldo_real)}: ${dif > 0 ? 'hay ' + pesos(dif) + ' de más' : 'faltan ' + pesos(-dif)}. ¿Qué fue?`,
      opciones: ops.filter(Boolean).map(o => ({ texto: o, valor: o })) };
  }
}

// ---------- Inversiones ----------
const buscarActivo = v => ctx.portafolio.find(p => norm(p.simbolo) === norm(v) || norm(p.nombre) === norm(v)) || null;
const platInv = cuentas.filter(c => c.Tipo === 'Inversión');
if (a === 'operacion_inversion') {
  d.tipo = norm(d.tipo) === 'venta' ? 'Venta' : 'Compra';
  const act = buscarActivo(d.activo);
  d.activo = act ? act.simbolo : String(d.activo || '').toUpperCase().trim();
  if (!d.activo) return charla('¿Qué activo compraste o vendiste? Por ejemplo: "compré 200 mil de bitcoin en Wenia desde Nequi".');
  d.nuevo = !act;
  d.tipo_activo = act ? act.tipo : (['Cripto', 'Stablecoin', 'ETF', 'Acción'].find(t => norm(t) === norm(d.tipo_activo)) || 'Cripto');
  d.plataforma = buscarCuenta(d.plataforma) || (act && act.cuenta) || (platInv.length === 1 ? platInv[0].ID : null);
  if (!d.plataforma) return charla(`¿En qué plataforma? Si es nueva, créala primero, por ejemplo: "crea una cuenta de inversión en trii".`);
  const precio = num(d.precio_usd) || (act ? act.precio : 0);
  d.total_usd = num(d.total_usd); d.total_cop = Math.round(monto(d.total_cop)); d.cantidad = num(d.cantidad); d.comision_cop = Math.round(monto(d.comision_cop));
  if (!d.total_cop && d.total_usd) d.total_cop = Math.round(d.total_usd * ctx.usdcop);
  if (!d.cantidad && precio) { const usd = d.total_usd || (d.total_cop ? d.total_cop / ctx.usdcop : 0); if (usd) { d.cantidad = +(usd / precio).toPrecision(8); d.cantidad_aprox = true; } }
  if (!d.total_cop && d.cantidad && precio) d.total_cop = Math.round(d.cantidad * precio * ctx.usdcop);
  if (!d.cantidad || !d.total_cop) return charla(`Necesito la cantidad o el valor de la ${d.tipo.toLowerCase()} de ${d.activo}. Por ejemplo: "compré 0,001 BTC por 250 mil" (o mándame la captura).`);
  if (d.tipo === 'Venta' && act && d.cantidad > act.cantidad * 1.0001) return charla(`Según mis registros tienes ${+act.cantidad.toFixed(8)} ${d.activo}; no alcanza para vender ${d.cantidad}. Si tienes más, dime "en Wenia tengo X ${d.activo}".`);
  d.fecha = (d.fecha && fecha(d.fecha).isValid ? fecha(d.fecha) : ahora).toFormat('yyyy-MM-dd'); d.operacion = OP;
  if (d.cuenta_pesos === 'NINGUNA') d.sin_pesos = true;
  else d.cuenta_pesos = buscarCuenta(d.cuenta_pesos);
  if (!d.cuenta_pesos && !d.sin_pesos) {
    pregunta = d.tipo === 'Compra'
      ? { idx: null, campo: 'cuenta_pesos', texto: `¿De dónde salieron los ${pesos(d.total_cop)} para comprar ${d.activo}?`, opciones: [...sugerir(d.total_cop, false).slice(0, 4), { texto: 'Ya estaba en la plataforma', valor: 'NINGUNA' }] }
      : { idx: null, campo: 'cuenta_pesos', texto: `¿A qué cuenta llegaron los ${pesos(d.total_cop)} de la venta de ${d.activo}?`, opciones: [...opsCuentas(principalesDestino).slice(0, 4), { texto: 'Se quedó en la plataforma', valor: 'NINGUNA' }] };
  } else if (d.tipo === 'Compra' && d.cuenta_pesos && !d.cuenta_pesos_ok && quedaNegativa(d.cuenta_pesos, d.total_cop, d.fecha) !== null) {
    pregunta = { idx: null, campo: 'cuenta_pesos', texto: `${nombreDe(d.cuenta_pesos)} quedaría en ${pesos(quedaNegativa(d.cuenta_pesos, d.total_cop, d.fecha))}. ¿Seguro que salió de ahí? Estas tienen saldo:`,
      opciones: [{ texto: `Sí, de ${nombreDe(d.cuenta_pesos)}`.slice(0, 28), valor: d.cuenta_pesos }, ...sugerir(d.total_cop, false, d.cuenta_pesos).slice(0, 3), { texto: 'Ya estaba en la plataforma', valor: 'NINGUNA' }] };
  } else {
    if (d.cuenta_pesos === 'NINGUNA') { d.sin_pesos = true; d.cuenta_pesos = null; }
    confirmar(`¿Registro esta ${d.tipo.toLowerCase()}?\n• ${d.cantidad_aprox ? '≈ ' : ''}${d.cantidad} ${d.activo}${d.nuevo ? ' (activo nuevo)' : ''} por ${pesos(d.total_cop)} en ${nombreDe(d.plataforma)}` +
      (d.sin_pesos ? '' : `\n• ${d.tipo === 'Compra' ? 'Sale de' : 'Llega a'} ${nombreDe(d.cuenta_pesos)}`) + (d.cantidad_aprox ? '\n(Cantidad aproximada con el precio de hoy; si tienes la cifra exacta, dímela o mándame la captura.)' : ''));
  }
}
if (a === 'ajustar_inversion') {
  const act = buscarActivo(d.activo);
  if (!act) return charla('No encontré ese activo. Escribe /inversiones para ver los que tienes.');
  d.activo = act.simbolo; d.plataforma = act.cuenta; d.cantidad_real = num(d.cantidad_real); d.diferencia = +(d.cantidad_real - act.cantidad).toPrecision(10); d.operacion = OP;
