      (esT && d.pago_total != null ? `\n💳 Según el banco: pago mínimo ${pesos(num(d.pago_minimo))} · pago total ${pesos(num(d.pago_total))}${d.fecha_pago ? ' · paga el ' + fecha(d.fecha_pago).setLocale('es').toFormat("d 'de' LLLL") : ''}.` : '') +
      (!esT && d.saldo_final != null ? `\nSaldo final del extracto: ${pesos(num(d.saldo_final))}.` : '') + cambioCorte;
    if (est.sugeridos || est.revisar) preguntar('¿Qué hago con los que faltan?', [
      { texto: est.revisar ? '✅ Registrar y revisar' : '✅ Registrar', valor: 'R' }, { texto: '⚡ Registrar todo ya', valor: 'TODO' }, { texto: '📥 Solo guardar', valor: 'G' }], { accion: 'revisar_extracto', lote, grupo: '_inicio' });
  }
}

if (a === 'revisar_extracto') {
  const lote = d.lote, g = d.grupo, el = String(d.eleccion || '');
  const filasLote = (T['Extractos'] || []).filter(x => String(x.ID).startsWith(lote + '-'));
  let n1 = 0, forzar = null, soloCuentas = false, prefijo = 'T';
  if (g === '_inicio') {
    if (el === 'G') r = 'Listo, dejé el extracto guardado sin registrar nada más. Cuando quieras, escribe /revisar.';
    else {
      const vuelven = new Set();
      for (const f of filasLote.filter(x => x.Estado === 'Sugerido' || (el === 'TODO' && x.Estado === 'Por revisar'))) { if (registrarFila(f, clSugerida(f))) n1++; else if (f.Estado === 'Sugerido') { f.Estado = 'Por revisar'; vuelven.add(f.ID); } }
      r = `Listo, registré ${n1} movimiento${n1 === 1 ? '' : 's'} del extracto.`;
    }
  } else if (g !== '_siguiente') {
    const fs = filasLote.filter(x => (x.Grupo || x['Descripción']) === g && x.Estado === 'Por revisar');
    if (el === 'T:?') { forzar = g; soloCuentas = true; r = 'Ok.'; }
    else if (el === 'PT') { forzar = g; soloCuentas = true; prefijo = 'PT'; r = '¿Desde qué cuenta pagaste la tarjeta?'; }
    else if (el === 'O') { for (const f of fs) { upd('Extractos', f.row_number, { Estado: 'Omitido' }); hechos.add(f.ID); } r = `Omití "${g}".`; }
    else {
      const [tipoC, val] = [el.split(':')[0], el.split(':').slice(1).join(':')];
      const cl = tipoC === 'G' ? { tipo: 'Gasto', categoria: val } : tipoC === 'I' ? { tipo: 'Ingreso', categoria: val } : tipoC === 'T' ? { tipo: 'Transferencia', cuenta2: val } : tipoC === 'PT' ? { tipo: 'Pago tarjeta', cuenta2: val } : { tipo: 'P' };
      for (const f of fs) if (registrarFila(f, cl)) n1++;
      // Aprende la regla para la próxima vez
      const persona = cl.tipo === 'P' ? (detDe(fs[0] || {}).p || titulo(g)) : '';
