      const existe = (T['Comercios'] || []).find(x => norm(x['Patrón']) === norm(g));
      const regla = { 'Patrón': g, Tipo: tipoR, 'Categoría': cl.categoria || '', Persona: persona, 'Cuenta contraparte': cl.cuenta2 || '', Veces: existe ? num(existe.Veces) + 1 : 1, Actualizado: creado };
      if (existe) upd('Comercios', existe.row_number, regla); else add('Comercios', regla);
      r = `Listo: "${g}" → ${cl.tipo === 'P' ? tipoR + ' (' + persona + ')' : cl.tipo + (cl.categoria ? ' · ' + cl.categoria : '') + (cl.cuenta2 ? ' · ' + nombreDe(cl.cuenta2) : '')} (${n1} movimiento${n1 === 1 ? '' : 's'}). Lo recordaré.`;
    }
  }
  if (!(g === '_inicio' && el === 'G') && !siguienteGrupo(lote, forzar, soloCuentas, prefijo)) r = (r ? r + '\n' : '') + '🎉 Terminamos: no queda nada por revisar de ese extracto.';
}

// ---------- v10: alias que aprendió al preguntar "¿Quién es tu …?" ----------
const aprendidos = [];
const aprenderAlias = (nombre, alias) => {
