if (d.alias_nuevo && d.persona_ok && d.persona) aprenderAlias(d.persona, d.alias_nuevo);
for (const m of (Array.isArray(d.movimientos) ? d.movimientos : [])) if (m.alias_nuevo && m.persona_ok && m.persona) aprenderAlias(m.persona, m.alias_nuevo);
if (aprendidos.length && r) r += `\n(Aprendí que ${aprendidos.join(' y ')}.)`;

// ---------- Alertas de presupuesto (80% y 100%) ----------
const nuevosMes = {};
for (const f of movRows) if (f.Tipo === 'Gasto' && String(f.Fecha).slice(0, 7) === mesAct) nuevosMes[f['Categoría']] = (nuevosMes[f['Categoría']] || 0) + num(f.Monto);
