    else if (antes < a1 && despues >= a1) r += `\n⚠️ Llevas el ${Math.round(despues * 100)}% del presupuesto de ${p.categoria} (${pesos((g[p.categoria] || 0) + nuevosMes[p.categoria])} de ${pesos(p.monto)}).`;
  }
}

const enlazar = movRows.filter(f => f.Detalle !== '4x1000').map(f => f.ID);
return [{ json: { ops, respuesta: r || 'Listo.', enlazar, siguiente } }];

// Convierte las filas en pedidos a la API de Google Sheets: un "append" por pestaña y un "batchUpdate" para las ediciones
const T = $('Tablas').first().json;
const ops = $('Ejecutar').first().json.ops || [];
const H = T._h || {};
const base = 'https://sheets.googleapis.com/v4/spreadsheets/1n97Po-FMwXt0XHwrSp4LLjCsyUMpKBdcUksFxkxJ8GM';
const col = i => { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const COL_FECHA = /^(Fecha|Creado|Modificado|Expira|Actualizado|Hora|Mes)/i;
const limpio = (v, col) => (typeof v === 'string' && (/^[=+@]/.test(v) || (!COL_FECHA.test(col || '') && /^\d{1,2}[\/:-]\d{1,2}([\/-]\d{2,4})?$/.test(v.trim())))) ? "'" + v : (v === undefined || v === null ? '' : v);
const items = [], porTabla = {};
for (const o of ops.filter(o => o.tipo === 'append' && (H[o.tabla] || []).length)) (porTabla[o.tabla] = porTabla[o.tabla] || []).push(H[o.tabla].map(h => limpio(o.fila[h], h)));
for (const [t, filas] of Object.entries(porTabla))
  items.push({ json: { url: `${base}/values/${encodeURIComponent("'" + t + "'!A1")}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`, body: { values: filas } } });
const data = [];
for (const o of ops.filter(o => o.tipo === 'update'))
  for (const [c, v] of Object.entries(o.cambios)) { const i = (H[o.tabla] || []).indexOf(c); if (i >= 0) data.push({ range: `'${o.tabla}'!${col(i)}${o.row}`, values: [[limpio(v, c)]] }); }
if (data.length) items.push({ json: { url: `${base}/values:batchUpdate`, body: { valueInputOption: 'USER_ENTERED', data } } });
return items.length ? items : [{ json: { vacio: true } }];

const e = $('Ejecutar').first().json;
