return [{ json: { respuesta: e.respuesta + (errores ? '\n⚠️ Hubo un problema guardando algo en la hoja; revisa Log Bot.' : ''), ok: !errores } }];

const tz = 'America/Bogota';
const ahora = DateTime.now().setZone(tz);
