// Montos: acepta 25000, "25.000", "$ 25.000,50", "(3.797.362)"
const num = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').trim();
  if (!s || s === '-') return 0;
  const neg = /^\(.*\)$/.test(s) || s.startsWith('-');
  s = s.replace(/[^\d,.]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if ((s.match(/\./g) || []).length > 1 || /\.\d{3}$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : (neg ? -n : n);
};
// Fechas: acepta 2026-09-29, 29/09/2026, con hora, o número de serie de Sheets
const fecha = v => {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: tz }).plus({ days: Math.floor(v) });
  const s = String(v || '').trim();
  for (const f of ['yyyy-MM-dd', 'd/M/yyyy', 'd/M/yy', 'yyyy-MM-dd H:mm', 'yyyy-MM-dd H:mm:ss', 'd/M/yyyy H:mm', 'd/M/yyyy H:mm:ss']) {
    const d = DateTime.fromFormat(s, f, { zone: tz });
    if (d.isValid) return d;
  }
  return DateTime.fromISO(s, { zone: tz });
};
const pesos = n => (n < 0 ? '-$' : '$') + String(Math.abs(Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

